// Copies metadataSchemas/curated_values.json (seed values of the curated-list slots, owned by graphql) into
// the webapp, validating it on the way. The webapp copy is generated by the webapp's dev/test/build scripts,
// never hand-edited.
//   yarn gen-curated-values
const fs = require('fs')
const path = require('path')

const SLOTS = ['sample_stabilisation', 'tissue_modification', 'genetic_background', 'maldi_matrix_application']

const source = path.join(__dirname, '..', 'metadataSchemas', 'curated_values.json')
const target = process.argv[2]
  || path.join(__dirname, '..', '..', 'webapp', 'src', 'lib', 'metadataSchemas', 'curated_values.generated.json')

const values = JSON.parse(fs.readFileSync(source, 'utf8'))
if (values === null || typeof values !== 'object' || Array.isArray(values)) {
  throw new Error('curated_values.json: must be an object of slot -> values')
}
const keys = Object.keys(values)
if (keys.length !== SLOTS.length || !SLOTS.every(slot => keys.includes(slot))) {
  throw new Error(`curated_values.json: keys must be exactly ${SLOTS.join(', ')}; got ${keys.join(', ')}`)
}
for (const [slot, list] of Object.entries(values)) {
  if (!Array.isArray(list) || list.length === 0) {
    throw new Error(`curated_values.json: slot "${slot}" must list at least one value`)
  }
  if (!list.every(value => typeof value === 'string' && value.trim() !== '')) {
    throw new Error(`curated_values.json: slot "${slot}" values must be non-empty strings`)
  }
}
fs.mkdirSync(path.dirname(target), { recursive: true })
fs.writeFileSync(target, JSON.stringify(values, null, 2) + '\n')
console.log(`Wrote ${keys.length} slots to ${path.relative(process.cwd(), target)}`)
